llm-multihead-split-merge.solution:
import numpy as np

def reshape_heads(x, num_heads, mode):
    x = np.asarray(x)
    if mode == "split":
        B, T, d = x.shape
        return x.reshape(B, T, num_heads, d // num_heads).transpose(0, 2, 1, 3)
    B, h, T, dh = x.shape
    return x.transpose(0, 2, 1, 3).reshape(B, T, h * dh)

