llm-bpe-train.solution:
from collections import Counter

def bpe_train(words, num_merges):
    vocab = Counter(tuple(w) for w in words if w)
    merges = []
    for _ in range(num_merges):
        pairs = Counter()
        for sym, f in vocab.items():
            for a, b in zip(sym, sym[1:]):
                pairs[(a, b)] += f
        if not pairs:
            break
        best = min(pairs, key=lambda p: (-pairs[p], p))
        merges.append([best[0], best[1]])
        new_vocab = Counter()
        for sym, f in vocab.items():
            out, i = [], 0
            while i < len(sym):
                if i + 1 < len(sym) and sym[i] == best[0] and sym[i + 1] == best[1]:
                    out.append(sym[i] + sym[i + 1])
                    i += 2
                else:
                    out.append(sym[i])
                    i += 1
            new_vocab[tuple(out)] += f
        vocab = new_vocab
    return merges

llm-wordpiece-tokenize.solution:
def wordpiece(text, vocab, unk="[UNK]", max_chars=100):
    vocab = set(vocab)
    out = []
    for word in text.split():
        if len(word) > max_chars:
            out.append(unk)
            continue
        pieces, start, bad = [], 0, False
        while start < len(word):
            end, cur = len(word), None
            while start < end:
                piece = word[start:end]
                if start > 0:
                    piece = "##" + piece
                if piece in vocab:
                    cur = piece
                    break
                end -= 1
            if cur is None:
                bad = True
                break
            pieces.append(cur)
            start = end
        out.extend([unk] if bad else pieces)
    return out

